{"code": "import pandas as pd
df = pd.read_csv('data.csv')
df['date'] = pd.to_datetime(df['date'], format='%m/%d/%y')
acct = df[df['account_id']=='xz8lX1K']

def day_delta(dstr, ref='2025-10-19'):
    a = acct[acct['date']==dstr]
    b = acct[acct['date']==ref]
    out={}
    for c in ['cloud_service','application','instance_family']:
        diff = a.groupby(c)['unblended_cost'].sum().subtract(b.groupby(c)['unblended_cost'].sum(), fill_value=0)
        out[c]=diff.sort_values()
    return out

for d in ['2025-10-27','2025-10-28']:
    print("====",d,"vs 10/19")
    o=day_delta(d)
    for c,s in o.items():
        print(c); print(s[(s.abs()>50)])
